INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63383982', 63383982, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Penyediaan jasa pemeliharaan KDO/KDO Khusus', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 142664408, 'March 2026', 'APBD', 1, 1, '5 Motor dan 4 Mobil', 'Pekerjaan ini meliputi penyediaan jasa pemeliharaan Kendaraan Dinas Operasional (KDO) dan KDO Khusus berupa mobil dan sepeda motor guna menjamin kendaraan selalu dalam kondisi laik jalan, aman, dan siap digunakan untuk mendukung kelancaran pelaksanaan tugas kedinasan. Pemeliharaan dilaksanakan secara berkala dan/atau insidentil sesuai kebutuhan, meliputi pemeriksaan, perawatan, perbaikan ringan, serta penggantian suku cadang habis pakai, dengan mengutamakan standar keselamatan, keandalan, dan ketentuan teknis yang berlaku.', 'Spesifikasi pekerjaan mencakup penyediaan jasa pemeliharaan untuk 4 (empat) unit mobil dinas dan 5 (lima) unit sepeda motor dinas, yang meliputi servis berkala, pemeriksaan mesin, sistem kelistrikan, sistem rem, sistem suspensi, sistem pendingin, penggantian oli mesin dan komponen pendukung lainnya, perbaikan ringan bodi, serta penggantian suku cadang yang mengalami keausan. Seluruh pekerjaan dilaksanakan oleh tenaga teknis yang kompeten menggunakan peralatan dan suku cadang sesuai spesifikasi pabrikan, dengan hasil pemeliharaan yang terdokumentasi dalam laporan pekerjaan dan dilaksanakan sesuai ketentuan peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 888233);
